import java.util.*;import java.util.function.BooleanSupplier;
/** Curved, continuous channels constrained to a drainage corridor, with soft riverbanks. */
final class NaturalRivers{
 static void trace(EnvironmentMap e,float[] original,EnvironmentNodes.Drainage flow,int start,int n,int size,int sea,double radius,double depth,float initial,double strength,long seed,BooleanSupplier stop){
  trace(e,original,flow,start,n,size,sea,radius,depth,initial,strength,seed,.85,.55,.65,stop);
 }
 static void trace(EnvironmentMap e,float[] original,EnvironmentNodes.Drainage flow,int start,int n,int size,int sea,double radius,double depth,float initial,double strength,long seed,double terrainFollow,double widthVariation,double bankVariation,BooleanSupplier stop){
  trace(e,original,flow,start,n,size,sea,radius,depth,initial,strength,seed,terrainFollow,widthVariation,bankVariation,false,stop);
 }
 static void trace(EnvironmentMap e,float[] original,EnvironmentNodes.Drainage flow,int start,int n,int size,int sea,double radius,double depth,float initial,double strength,long seed,double terrainFollow,double widthVariation,double bankVariation,boolean courses,BooleanSupplier stop){
  if(courses&&e.riverFlow!=null&&e.riverFlow.discharge()[start]<=0)return;
  if(courses)e.riverNetworkCells=e.riverNetworkCells==null?new BitSet(n*n):(BitSet)e.riverNetworkCells.clone();ArrayList<Integer> networkPath=new ArrayList<>();boolean joined=false;
  ArrayList<double[]> route=new ArrayList<>();int cell=start,stride=courses?1:Math.max(3,n/256),steps=0;boolean[] seen=new boolean[n*n];
  while(cell>=0&&!seen[cell]&&steps<n*n){if((steps&255)==0)EnvironmentNodes.cancel(stop);seen[cell]=true;int x=cell%n,z=cell/n;boolean connection=courses?e.riverNetworkCells.get(cell):e.river[cell]>.2&&e.waterY(cell,sea)>Math.round(e.height[cell]);boolean end=steps>0&&(original[cell]<=sea||connection||!courses&&!Float.isFinite(initial)&&e.waterY(cell,sea)>sea&&e.waterY(cell,sea)>original[cell]+1);if(steps>0&&connection)joined=true;networkPath.add(cell);
   if(steps%stride==0||end)route.add(new double[]{x,z});if(end)break;int next=flow.parent()[cell];if(next<0){if(steps%stride!=0)route.add(new double[]{x,z});break;}cell=next;steps++;
  }
  if(route.size()<2)return;if(courses)for(int i:networkPath)e.riverNetworkCells.set(i);
  float[] steering=original;if(courses&&e.riverCatchment!=null){steering=original.clone();for(int i=0;i<steering.length;i++){double pit=flow.level()[i]-original[i];if(pit>1)steering[i]=(float)(flow.level()[i]+pit*3);}}
  for(int pass=0;pass<3;pass++){ArrayList<double[]> smooth=new ArrayList<>();smooth.add(route.get(0));for(int i=0;i<route.size()-1;i++){double[] a=route.get(i),b=route.get(i+1);smooth.add(safe(a[0]*.75+b[0]*.25,a[1]*.75+b[1]*.25,a,original,flow.level(),n,courses,size/(double)n,.18));smooth.add(safe(a[0]*.25+b[0]*.75,a[1]*.25+b[1]*.75,b,original,flow.level(),n,courses,size/(double)n,.18));}smooth.add(route.get(route.size()-1));route=smooth;}
  double block=size/(double)n,wavelength=Math.max(radius*16,Math.max(96/block,n*.02)),amplitude=Math.min(wavelength*.06,Math.max(radius*1.2,4/block)*strength);float previous=initial;double px=0,pz=0,arc=0;
  ArrayList<double[]> curved=new ArrayList<>();
  for(int k=0;k<route.size();k++){double[] point=route.get(k),before=route.get(Math.max(0,k-1)),after=route.get(Math.min(route.size()-1,k+1));if(k>0)arc+=Math.hypot(point[0]-before[0],point[1]-before[1]);double tx=after[0]-before[0],tz=after[1]-before[1],length=Math.max(.0001,Math.hypot(tx,tz));double fade=TerraForge.smooth(Math.min(1,Math.min(k,route.size()-1-k)/16.)),offset=(TerraForge.sample(arc/wavelength,.37,seed+31)*2-1)*amplitude*fade;if(courses)offset=0;offset=RiverShape.terrainOffset(steering,n,point[0],point[1],-tz/length,tx/length,radius,block,offset,terrainFollow)*fade;double xx=point[0]-tz/length*offset,zz=point[1]+tx/length*offset;
   int source=clamp((int)Math.round(point[1]),n)*n+clamp((int)Math.round(point[0]),n),shifted=clamp((int)Math.round(zz),n)*n+clamp((int)Math.round(xx),n);double damp=1/(1+Math.max(0,steering[shifted]-steering[source]-2)/4);curved.add(safe(point[0]+(xx-point[0])*damp,point[1]+(zz-point[1])*damp,point,original,flow.level(),n,courses,size/(double)n,.18));}
  // Round displacement changes before carving; the path never jitters independently on X and Z.
  for(int pass=0;pass<24;pass++){ArrayList<double[]> rounded=new ArrayList<>();rounded.add(curved.get(0));for(int k=1;k<curved.size()-1;k++){double[] a=curved.get(k-1),b=curved.get(k),c=curved.get(k+1);rounded.add(safe(a[0]*.25+b[0]*.5+c[0]*.25,a[1]*.25+b[1]*.5+c[1]*.25,b,original,flow.level(),n,courses,size/(double)n,.18));}rounded.add(curved.get(curved.size()-1));curved=rounded;}
  ArrayList<RiverRibbon.Point> ribbon=new ArrayList<>();arc=0;for(int k=0;k<curved.size();k++){EnvironmentNodes.cancel(stop);double[] point=curved.get(k),before=curved.get(Math.max(0,k-1)),after=curved.get(Math.min(curved.size()-1,k+1));double xx=point[0],zz=point[1],tx=after[0]-before[0],tz=after[1]-before[1],tlen=Math.max(.0001,Math.hypot(tx,tz)),nx=-tz/tlen,nz=tx/tlen;if(k>0)arc+=Math.hypot(xx-before[0],zz-before[1]);double centerHeight=RiverShape.height(original,n,xx,zz),sides=(RiverShape.height(original,n,xx+nx*radius*2,zz+nz*radius*2)+RiverShape.height(original,n,xx-nx*radius*2,zz-nz*radius*2))*.5,confinement=Math.max(0,Math.min(1,(sides-centerHeight)/16)),widthFactor=RiverShape.widthFactor(arc*block,radius*block,widthVariation,seed,confinement),leftBank=RiverShape.traceBankFactor(arc*block,-1,bankVariation,seed),rightBank=RiverShape.traceBankFactor(arc*block,1,bankVariation,seed);
   double currentDischarge=RiverFlow.pathDischarge(e.riverFlow,networkPath,k/(double)(curved.size()-1),joined);if(k==0){px=xx;pz=zz;}int samples=Math.max(1,(int)Math.ceil(Math.hypot(xx-px,zz-pz)*3));
   for(int j=1;j<=samples;j++){double x=px+(xx-px)*j/samples,z=pz+(zz-pz)*j/samples;int ci=clamp((int)Math.round(z),n)*n+clamp((int)Math.round(x),n);float level=Math.max(sea,Math.min(previous,(float)Math.floor(original[ci])));previous=level;double localMaturity=RiverCourse.maturity(level,sea,0,k/(double)(curved.size()-1)),physicalWidth=radius*(.85+.3*Math.sqrt(k/(double)(curved.size()-1)))*widthFactor*RiverFlow.widthFactor(currentDischarge,localMaturity),channelDepth=courses&&n==size?Math.min(5,RiverCourse.depth(depth,localMaturity)*RiverFlow.depthFactor(currentDischarge)):depth;double width=courses&&n==size?Math.max(.65,physicalWidth):Math.max(.65,radius*(.7+.55*Math.sqrt(k/(double)(curved.size()-1)))*widthFactor),bank=width*2+1,reach=width+bank*Math.max(leftBank,rightBank);int r=(int)Math.ceil(reach);
    for(int dz=-r;dz<=r;dz++)for(int dx=-r;dx<=r;dx++){int ix=(int)Math.round(x)+dx,iz=(int)Math.round(z)+dz;if(ix<0||iz<0||ix>=n||iz>=n)continue;int i=iz*n+ix;double distance=Math.hypot(ix-x,iz-z);double side=(ix-x)*nx+(iz-z)*nz,localReach=width+bank*(side<0?leftBank:rightBank);if(distance>localReach||original[i]<=sea-1)continue;
     if(distance<=width){double f=distance/width;e.height[i]=(float)Math.min(e.height[i],level-Math.max(1,channelDepth*(1-f*f)));boolean reservoir=e.water[i]>original[i]+depth+2;float localLevel=Math.min(level,Math.max(sea,(float)Math.floor(original[i])+1));e.water[i]=reservoir?e.water[i]:e.river[i]>.05?Math.min(e.water[i],localLevel):Math.max(e.water[i],localLevel);e.river[i]=(float)Math.max(e.river[i],1-f*.5);e.material[i]=7;}
     else if(original[i]>e.waterY(i,sea)){double join=1-TerraForge.smooth(Math.min(1,(distance-width)/(localReach-width)));double bankHeight=level+.7+(distance-width)*block*.22;double cut=Math.min(e.height[i],bankHeight);e.height[i]=(float)(e.height[i]+(cut-e.height[i])*join);if(distance<width*1.5)e.material[i]=7;}
    }
   }int center=clamp((int)Math.round(zz),n)*n+clamp((int)Math.round(xx),n);double discharge=currentDischarge;double rr=Math.max(.5/block,radius*(.85+.3*Math.sqrt(k/(double)(curved.size()-1)))*widthFactor);if(courses){double progress=k/(double)(curved.size()-1),gradient=Math.max(0,(RiverShape.height(original,n,before[0],before[1])-RiverShape.height(original,n,after[0],after[1]))/Math.max(block,Math.hypot(after[0]-before[0],after[1]-before[1])*block));double maturity=RiverCourse.maturity(e.waterY(center,sea),sea,gradient,progress);rr*=Double.isFinite(discharge)?RiverFlow.widthFactor(discharge,maturity):RiverCourse.width(maturity,EnvironmentMap.at(e.riverCatchment,center,1500));if(e.waterY(center,sea)<sea+8)rr*=1+.45*Math.max(0,1-(e.waterY(center,sea)-sea)/8.);}ribbon.add(new RiverRibbon.Point(xx*block,zz*block,rr*block,previous,discharge));px=xx;pz=zz;
  }
  if((!courses||joined)&&e.ribbons!=null&&!ribbon.isEmpty()){var end=ribbon.get(ribbon.size()-1);double best=192*192;RiverRibbon.Point join=null;for(var segment:e.ribbons.query((int)end.x(),(int)end.z())){var a=segment.a();var b=segment.b();double dx=b.x()-a.x(),dz=b.z()-a.z(),t=Math.max(0,Math.min(1,((end.x()-a.x())*dx+(end.z()-a.z())*dz)/Math.max(.001,dx*dx+dz*dz)));var p=RiverRibbon.lerp(a,b,t);double distance=Math.pow(p.x()-end.x(),2)+Math.pow(p.z()-end.z(),2);if(distance<best){best=distance;join=new RiverRibbon.Point(p.x(),p.z(),end.radius(),p.water(),end.discharge());}}if(join!=null)ribbon.set(ribbon.size()-1,join);}
  if(courses&&n==size)e.resolvedRiverChannels=true;
  e.ribbons=(e.ribbons==null?new RiverRibbon.Network(List.of()):e.ribbons).append(ribbon,depth,seed,steering,n,block,terrainFollow,courses);
 }
 static double[] safe(double x,double z,double[] anchor,float[] terrain,float[] spill,int n,boolean courses,double block,double maximumSlope){
  double[] point=safe(x,z,anchor,terrain,spill,n,courses);if(!courses)return point;
  int samples=Math.max(1,(int)Math.ceil(Math.hypot(point[0]-anchor[0],point[1]-anchor[1])*4));
  for(int k=1;k<=samples;k++){double t=k/(double)samples;if(RiverCourse.terrainSlope(terrain,n,anchor[0]+(point[0]-anchor[0])*t,anchor[1]+(point[1]-anchor[1])*t,block)>maximumSlope)return anchor.clone();}return point;
 }
 static double[] safe(double x,double z,double[] anchor,float[] terrain,float[] spill,int n,boolean courses){
  if(!courses)return new double[]{x,z};
  // Check the displacement corridor, not only the final vertex, so rounding cannot cross a hole.
  int steps=Math.max(1,(int)Math.ceil(Math.hypot(x-anchor[0],z-anchor[1])*4));
  for(int j=1;j<=steps;j++){double t=j/(double)steps;int i=clamp((int)Math.round(anchor[1]+(z-anchor[1])*t),n)*n+clamp((int)Math.round(anchor[0]+(x-anchor[0])*t),n);if(spill[i]-terrain[i]>1.5||terrain[i]>RiverShape.height(terrain,n,anchor[0],anchor[1])+1.5)return anchor.clone();}
  return new double[]{x,z};
 }
 static int clamp(int a,int n){return Math.max(0,Math.min(n-1,a));}
}
